import java.util.Map;

class Order {
    private final String id;
    private final String method;
    Order(String id, String method) { this.id = id; this.method = method; }
    String getId() { return id; }
    String getMethod() { return method; }
}

class Receipt {
    private final boolean success;
    private final String orderId;
    Receipt(boolean success, String orderId) { this.success = success; this.orderId = orderId; }
    public String toString() { return "Receipt{success=" + success + ", orderId=" + orderId + "}"; }
}

interface PaymentMethod {
    Receipt charge(Order order);
}

class PaymentProcessor {
    private final Map<String, PaymentMethod> methods;
    PaymentProcessor(Map<String, PaymentMethod> methods) { this.methods = methods; }
    Receipt charge(Order order) {
        PaymentMethod method = methods.get(order.getMethod());
        if (method == null) throw new IllegalArgumentException("Unknown payment method");
        return method.charge(order);
    }
}

class FakePaymentMethod implements PaymentMethod {
    public Receipt charge(Order order) { return new Receipt(true, order.getId()); }
}

public class Main {
    public static void main(String[] args) {
        PaymentProcessor processor = new PaymentProcessor(Map.of("fake", new FakePaymentMethod()));
        // test dispatch logic with zero real payment infrastructure involved
        System.out.println(processor.charge(new Order("order-6", "fake")));
    }
}

