#include <iostream>
#include <string>
#include <unordered_map>
#include <memory>
#include <stdexcept>

class Order {
public:
    Order(std::string id, std::string method) : id_(std::move(id)), method_(std::move(method)) {}
    const std::string& getId() const { return id_; }
    const std::string& getMethod() const { return method_; }

private:
    std::string id_;
    std::string method_;
};

class Receipt {
public:
    Receipt(bool success, std::string orderId) : success_(success), orderId_(std::move(orderId)) {}
    bool isSuccess() const { return success_; }
    const std::string& getOrderId() const { return orderId_; }

private:
    bool success_;
    std::string orderId_;
};

class PaymentMethod {
public:
    virtual ~PaymentMethod() = default;
    virtual Receipt charge(const Order& order) = 0;
};

class PaymentProcessor {
public:
    explicit PaymentProcessor(std::unordered_map<std::string, std::shared_ptr<PaymentMethod>> methods)
        : methods_(std::move(methods)) {}

    Receipt charge(const Order& order) {
        auto it = methods_.find(order.getMethod());
        if (it == methods_.end()) throw std::invalid_argument("Unknown payment method");
        return it->second->charge(order);
    }

private:
    std::unordered_map<std::string, std::shared_ptr<PaymentMethod>> methods_;
};

class FakePaymentMethod : public PaymentMethod {
public:
    Receipt charge(const Order& order) override { return Receipt(true, order.getId()); }
};

int main() {
    std::unordered_map<std::string, std::shared_ptr<PaymentMethod>> methods;
    methods["fake"] = std::make_shared<FakePaymentMethod>();
    PaymentProcessor processor(methods);
    // test dispatch logic with zero real payment infrastructure involved
    Receipt receipt = processor.charge(Order("order-6", "fake"));
    std::cout << "Receipt{success=" << (receipt.isSuccess() ? "true" : "false")
              << ", orderId=" << receipt.getOrderId() << "}" << std::endl;
    return 0;
}
